def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([5, 5]), fmt([1, 2, 3]), fmt([3, 2, 1]), fmt([2, 2, 2, 2]), fmt([4, 4, 4, 9, 9]), fmt([5, 1, 2, 3]), fmt([10**9, 10**9, 10**9]), fmt([1, 1, 1, 1, 1, 1])]
    for _ in range(20):
        n = rng.randint(1, 6)
        tests.append(fmt([rng.randint(1, 6) for _ in range(n)]))
    for _ in range(8):
        n = rng.randint(7, 40)
        tests.append(fmt([rng.randint(1, rng.choice([5, 10, 30])) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt([10**9] * 100000))
    tests.append(fmt([rng.randint(1, 1000) for _ in range(100000)]))
    tests.append(fmt([100000 - i for i in range(100000)]))
    tests.append(fmt([rng.randint(1, 100000) for _ in range(100000)]))
    return tests
